INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3304-4000-8000-000000000004', 'b1b2c3d4-3333-4000-8000-000000000003', 4, 'Reflexão: Minha História Vocacional', 'Olhar para trás para enxergar adiante', '{"text": "Reflita sobre sua hist\u00f3ria pessoal \u00e0 luz do chamado de Deus:\n\n1. **Quais momentos da minha vida me trouxeram maior paz e realiza\u00e7\u00e3o?**\n2. **Quando me senti mais pr\u00f3ximo de Deus?**\n3. **Que talentos e dons recebi que poderiam servir aos outros?**\n4. **H\u00e1 algum desejo persistente no meu cora\u00e7\u00e3o que nunca desaparece?**\n5. **O que as pessoas que me conhecem bem dizem sobre meus dons?**\n\nEscreva suas respostas no di\u00e1rio espiritual. N\u00e3o tenha pressa \u2014 o discernimento \u00e9 um processo.", "prompt": "Descreva um momento em que voc\u00ea sentiu profundamente que Deus estava falando com voc\u00ea. O que aconteceu? Como se sentiu?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;